// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Lets try to optimize that"
// Changes: Join single-predecessor jump targets so scalar cleanup can see
// through copies.
#include "optimizer_jump_threading.h"

#include <string.h>

bool optimizer_merge_linear_blocks(Ctx* ctx, IrFunctionId fid) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  size_t* incoming = ctx->optimizer.block_data;

  memset(incoming, 0, fn->blocks.count * sizeof(*incoming));

  // Count function entry as an edge so a backedge cannot absorb the entry.
  incoming[fn->entrypoint]++;
  for (IrBlockId bid = 0; bid < fn->blocks.count; bid++) {
    const IrBlockTerminator* term = &fn->blocks.data[bid].terminator;

    if (term->type == IR_TERMINATOR_JUMP)
      incoming[term->value.jump_target]++;
    else if (term->type == IR_TERMINATOR_CONDITIONAL) {
      incoming[term->value.conditional_target.true_target]++;
      incoming[term->value.conditional_target.false_target]++;
    }
  }

  bool changed = false;
  for (IrBlockId bid = 0; bid < fn->blocks.count; bid++) {
    IrBlock* block = &fn->blocks.data[bid];
    while (block->terminator.type == IR_TERMINATOR_JUMP) {
      IrBlockId id = block->terminator.value.jump_target;

      if (id == bid || incoming[id] != 1)
        break;

      IrBlock* next = &fn->blocks.data[id];
      IrInstructionArray* into = &block->instructions;
      IrInstructionArray* from = &next->instructions;

      if (from->count) {
        size_t count = into->count + from->count;

        if (into->capacity < count) {
          if (into->data)
            TRY_REALLOC(into->data, count * sizeof(*into->data));
          else
            into->data = TRY_MALLOC(count * sizeof(*into->data));
          into->capacity = count;
        }

        memcpy(into->data + into->count, from->data,
               from->count * sizeof(*from->data));

        into->count = count;
        from->count = 0;
      }

      block->terminator = next->terminator;
      // Disconnect the emptied block without transferring ownership twice.
      next->terminator = (IrBlockTerminator){.type = IR_TERMINATOR_JUMP,
                                             .value.jump_target = id};

      incoming[id] = 0;
      changed = true;
    }
  }

  return changed;
}
